-- Sơ đồ CSDL tham khảo (MySQL). Khi chạy dự án nên dùng: php artisan migrate --seed
CREATE DATABASE IF NOT EXISTS newsdb CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci; USE newsdb;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'editor');
CREATE TABLE categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,slug VARCHAR(255) NOT NULL UNIQUE,description TEXT NULL);
CREATE TABLE articles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,title VARCHAR(255) NOT NULL,slug VARCHAR(255) NOT NULL UNIQUE,summary TEXT NULL,content LONGTEXT NOT NULL,image VARCHAR(255) NULL,category_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,views INT UNSIGNED DEFAULT 0,status VARCHAR(20) DEFAULT 'published',published_at TIMESTAMP NULL,FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE comments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,article_id BIGINT UNSIGNED NOT NULL,author_name VARCHAR(100) NOT NULL,content TEXT NOT NULL,is_approved TINYINT(1) DEFAULT 0,FOREIGN KEY(article_id) REFERENCES articles(id) ON DELETE CASCADE);
CREATE TABLE contacts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255),email VARCHAR(255),subject VARCHAR(255),message TEXT);
